  /** Release ZIP the owner uploads to JVZoo (file name only). */
  zip: string;
  /** Cover JPG delivered as the listing image (file name only). */
  coverFile: string;
  /** JVZoo shelf for this course, from kit §3. */
  category: string;
  /** The kit's long-form sales-page copy — verbatim, line-based. */
